$(document).ready(function() {
    const userEmail = frappe.session.user; // Assuming employee is the logged-in user
    const button = root_element.querySelector('#myButton');
    const statusButton = root_element.querySelector('#checkin-status');
    const lastCheckinTimeSpan = root_element.querySelector('#lastCheckinTime');
    const empNameH1Tag = root_element.querySelector('#emp_name');



    function formatDateTime(input) {
        const inputDate = new Date(input);
        const now = new Date();

        // Function to check if two dates are the same day
        function isSameDay(date1, date2) {
            return date1.getFullYear() === date2.getFullYear() &&
                   date1.getMonth() === date2.getMonth() &&
                   date1.getDate() === date2.getDate();
        }

        // Determine the appropriate date label
        let dateLabel;
        if (isSameDay(inputDate, now)) {
            dateLabel = "";
        } else if (isSameDay(inputDate, new Date(now.getTime() - 86400000))) {
            dateLabel = "yesterday";
        } else {
            dateLabel = inputDate.toISOString().split('T')[0];
        }

        // Format time in 12-hour format
        let hours = inputDate.getHours();
        const minutes = inputDate.getMinutes().toString().padStart(2, '0');
        const seconds = inputDate.getSeconds().toString().padStart(2, '0');
        const ampm = hours >= 12 ? 'PM' : 'AM';
        hours = hours % 12;
        hours = hours ? hours : 12; // the hour '0' should be '12'
        const time12hr = `${hours.toString().padStart(2, '0')}:${minutes}:${seconds} ${ampm}`;

        // Print the result
        return`at ${time12hr} ${dateLabel}`;
    }





    // Function to fetch employee ID based on user email
    function fetchEmployeeId(email) {
        return frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Employee",
                fields: ["name", "first_name"],
                filters: { "user_id": email }
            }
        }).then(response => {
            if (response.message && response.message.length > 0) {
                console.log("-----------", response.message)
                return response.message[0];
            } else {
                return null;
            }
        });
    }

    // Function to fetch the latest check-in/check-out status based on employee ID
    function fetchCheckinStatus(employeeId) {
        return frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Employee Checkin",
                fields: ["log_type", "time"],
                filters: { employee: employeeId },
                order_by: "time desc",
                limit: 1
            }
        }).then(response => {
            if (response.message && response.message.length > 0) {
                return response;
            } else {
                console.log("No check-in/check-out records found");
                return "check-out";
            }
        });
    }

    // Function to create a new check-in/check-out log
    function createCheckinLog(employeeId, logType) {
        return frappe.call({
            method: "frappe.client.insert",
            args: {
                doc: {
                    doctype: "Employee Checkin",
                    employee: employeeId,
                    log_type: logType,
                    time: frappe.datetime.now_datetime(),
                    device_id: "Mobile"
                }
            }
        }).then(response => {
            return response.message;
        });
    }

    // Compute the next action based on the current status
    function getNextAction(status) {
        if (status === "check-in") {
            return { action: "OUT", label: "Check Out" };
        } else {
            return { action: "IN", label: "Check In" };
        }
    }


    function getLogAction(status) {

        if (status === "check-in") {
            return { action: "IN", label: "Check In" };
        } else {
            return { action: "OUT", label: "Check Out" };
        }
    }


    function getCheckinStatus(status) {

        if (status === "check-out"){
            return "check-out";
        }else{
            const latestLog = status.message[0];
            if (latestLog.log_type === "IN"){
                return "check-in";
            } else {

                return "check-out";
            }
        }

    }

    // Function to update button text based on check-in/check-out status
    function updateButtonText() {
        fetchEmployeeId(userEmail).then(employeeId => {
            if (employeeId) {
                fetchCheckinStatus(employeeId.name).then(status => { 
                    const latestLogVal = getCheckinStatus(status);

                    const nextAction = getNextAction(latestLogVal);
                    $(button).text(nextAction.label);

                    if(status !== "check-out"){
                        const date_time_log = formatDateTime(status.message[0].time);
                        const LogAction = getLogAction(latestLogVal);
                        $(lastCheckinTimeSpan).text(`Last ${LogAction.label.toLowerCase()} was ${date_time_log}`);
                    }

                    $(empNameH1Tag).text(`Hey, ${employeeId.first_name}`);
                });
            } else {
                $(button).hide(); 
                // $(button).text("Employee ID not found");
                $(empNameH1Tag).text("You’re not an employee");
            }
        });
    }

    // Initial update of button text on page load
    updateButtonText();

    // Event handler for the button click
    $(button).click(function() {
        fetchEmployeeId(userEmail).then(employeeId => {
            if (employeeId) {
                fetchCheckinStatus(employeeId.name).then(status => {
                    const latestLogVal = getCheckinStatus(status);
                    const nextAction = getNextAction(latestLogVal);
                    $(button).text(nextAction.label);

                    createCheckinLog(employeeId.name, nextAction.action).then(() => {
                        // After creating the log, update the button text
                        updateButtonText();
                    });
                });
            } else {
                $(button).hide(); 
                // $(statusButton).text("Employee ID not found");
            }
        });
    });
});
